import 'package:flutter_test/flutter_test.dart';import 'package:auren/services/creator/creator_growth_repository.dart';void main(){test('empty creator average is zero',(){const s=AurenCreatorGrowthSummary(posts:0,likes:5,comments:2,mediaPosts:0,scheduled:2);expect(s.avgLikes,0);});test('comments are tracked in growth summary',(){const s=AurenCreatorGrowthSummary(posts:4,likes:20,comments:7,mediaPosts:3,scheduled:1);expect(s.comments,7);expect(s.avgLikes,5);});test('ai draft is retained on creator plan item',(){const p=AurenCreatorPlanItem(id:'1',title:'Test',format:'short',status:'draft',aiDraft:'Hook\nScript');expect(p.aiDraft,'Hook\nScript');});}